export const getCreateDownloadUrl = () => {




  return `/api/downloads`
}

/**
 * @summary Create a download job
 */
export const createDownload = async (downloadRequest: DownloadRequest, options?: RequestInit): Promise<DownloadJob> => {

  return customFetch<DownloadJob>(getCreateDownloadUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      downloadRequest,)
  }
);}




